{
  "name": "reTerminal Sticky",
  "category": "data",
  "description": "Made for the Seeed reTerminal Sticky. The scene fills the glass. The scene list becomes a home screen with the time, the date, the battery and the signal, and under it how to get around: what each key does and the swipes, as the frame's event map has them. Swipe up for the list and down for the settings. The Go key, the top one, goes: pressed once it opens what is picked, twice it goes back, three times home to the list. Or a status bar over the scene. Its settings choose what it shows, the time format, white on black and the text size, and what the Go key does for it.",
  "version": "1.0.1",
  "fields": [],
  "output": [
    {
      "name": "image",
      "type": "image"
    }
  ],
  "events": [
    "button"
  ]
}

