// The reTerminal Sticky's own layout: the scene on the whole glass, and a home
// screen around the scene list with the time, the battery, and how to get
// around: what each key does and the swipes, read off the frame's event map.
// Swipe up from the bottom for the scene list, down from the top for the
// settings, in from a side for the scene's back and forward. One other look:
// a status bar. What it shows, and what the Go key does for the layout, are
// its settings.
// Black on white, or white on black (the "Colors" setting, put in place at
// the start of each render).
let INK = '#000000'
let GREY = '#555555'
let PALE = '#aaaaaa'
let PAPER = '#ffffff'

const pad = (n) => String(n).padStart(2, '0')

// The layout's settings as it uses them. A switch comes as true / false or as
// its text, and is on until it is turned off.
const on = (value) => value !== false && value !== 'false'
const SIZES = { small: 0.85, normal: 1, large: 1.2 }
function settingsOf(state) {
  return {
    home: on(state.home),
    refresh: on(state.refresh),
    listKey: on(state.listKey),
    date: on(state.date),
    swipes: on(state.swipes),
    signal: on(state.signal),
    battery: on(state.battery),
    clock: state.clock === '12' || state.clock === 'off' ? state.clock : '24',
    dark: state.colors === 'dark',
    scale: SIZES[state.size] || 1,
  }
}
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October',
  'November', 'December']

// What the frame's own event map says on a Sticky, for a frame that has none
// to tell (the preview): fos_board.c's STICKY_KEYS (the Go key twice back,
// three times the scene list, held voice chat) and the edge swipes.
const STICKY_MAP = [
  { event: 'button', match: { label: 'UP', action: 'longPress' }, emit: 'setCurrentScene', as: { direction: 'prev' } },
  { event: 'button', match: { label: 'DOWN', action: 'longPress' }, emit: 'setCurrentScene', as: { direction: 'next' } },
  { event: 'button', match: { label: 'AI', action: 'doublePress' }, emit: 'back', as: {} },
  { event: 'button', match: { label: 'AI', action: 'triplePress' }, emit: 'sceneSwitcher', as: {} },
  { event: 'button', match: { label: 'AI', action: 'longPress' }, emit: 'voiceChat', as: {} },
  { event: 'edgeSwipe', match: { edge: 'left' }, emit: 'back', as: {} },
  { event: 'edgeSwipe', match: { edge: 'right' }, emit: 'forward', as: {} },
  { event: 'edgeSwipe', match: { edge: 'bottom' }, emit: 'sceneSwitcher', as: {} },
  { event: 'edgeSwipe', match: { edge: 'top' }, emit: 'sceneSettings', as: {} },
]
// The Go key, the one a hand finds (Seeed prints AI on it, and AI stays its
// label in the event map): pressed it goes, twice it goes back, three times
// home. The layout listens to it too: a double press opens the scene list,
// where the frame's map leaves that free, and a press, where the map leaves
// the press to the scene, draws the picture again.
const LIST_KEY = 'AI'

// Icons, one path each in a 0 0 24 24 box (Material Design Icons).
const ICON = {
  apps: 'M4,4H10V10H4V4M14,4H20V10H14V4M4,14H10V20H4V14M14,14H20V20H14V14Z',
}

const Icon = ({ d, size }) => (
  <svg viewBox="0 0 24 24" width={size} height={size}>
    <path d={d} fill="currentColor" />
  </svg>
)

// What the frame's event map makes of a key, in a word. Under an arrow that
// already says which way, a scene change is just "Scene".
function said(rule) {
  switch (rule.emit) {
    case 'setCurrentScene': return 'Scene'
    case 'voiceChat': return 'Talk'
    case 'sceneSwitcher': return 'Scenes'
    case 'sceneSettings': return 'Settings'
    case 'toggleScreen': return 'Screen'
    case 'render': return 'Refresh'
    case 'back': return 'Back'
    case 'forward': return 'Forward'
    default: return rule.emit ? String(rule.emit) : null
  }
}
function keyRule(map, label, action) {
  return map.find((rule) => rule.event === 'button' && rule.match && rule.match.label === label &&
    (rule.match.action || 'press') === action)
}
const swipeRule = (map, edge) => map.find((rule) => rule.event === 'edgeSwipe' && rule.match && rule.match.edge === edge)
const eventMap = (frame) => (Array.isArray(frame.eventMap) ? frame.eventMap : STICKY_MAP)

// The scene list is showing (built in, its id `system/sceneSwitcher`).
const listShows = (frame) => frame.systemScene === true && String(frame.sceneId || '').startsWith('system/sceneSwitcher')

// The layout's own double press opens the list where the frame's map leaves it
// free and the owner has not turned it off.
const listKeyFree = (map, set) => set.listKey && !keyRule(map, LIST_KEY, 'doublePress')

export function onEvent(app, context) {
  const press = context.payload || {}
  if (context.event !== 'button' || press.label !== LIST_KEY || app.frame.systemScene) return false
  const set = settingsOf(app.state)
  // A press the frame's map binds never reaches the layout: this one is free.
  if ((press.action || 'press') === 'press' && set.refresh) frameos.dispatch('render')
  if (press.action === 'doublePress' && listKeyFree(eventMap(app.frame), set)) {
    frameos.dispatch('sceneSwitcher')
  }
  return false
}

// Four bars for the Wi-Fi signal, nothing on a frame that cannot tell.
function Signal({ rssi, u, color }) {
  if (typeof rssi !== 'number') return null
  const level = rssi >= -55 ? 4 : rssi >= -65 ? 3 : rssi >= -75 ? 2 : 1
  return (
    <div className={`flex items-end gap-[${Math.max(1, Math.round(u * 0.4))}px] h-[${Math.round(u * 3)}px]`}>
      {[0.3, 0.55, 0.8, 1].map((share, i) => (
        <div className={`w-[${Math.max(2, Math.round(u * 0.6))}px] h-[${Math.round(u * 3 * share)}px] ${i < level ? `bg-[${color}]` : `bg-[${PALE}]`}`} />
      ))}
    </div>
  )
}

function Battery({ percent, u, color }) {
  if (typeof percent !== 'number') return null
  const w = Math.round(u * 5)
  const h = Math.round(u * 2.6)
  const line = Math.max(1, Math.round(u * 0.3))
  const inner = Math.max(0, Math.round((w - 4 * line) * Math.min(100, Math.max(0, percent)) / 100))
  return (
    <div className="flex items-center gap-[3px]">
      <div className={`flex items-center w-[${w}px] h-[${h}px] p-[${line}px] border-[${line}px] border-[${color}] rounded-[${line * 2}px]`}>
        <div className={`h-full w-[${inner}px] bg-[${color}]`} />
      </div>
      <div className={`w-[${line * 2}px] h-[${Math.round(h / 2.5)}px] bg-[${color}]`} />
      <span className={`pl-[${line * 2}px] text-[${Math.round(u * 3)}px] font-semibold`}>{`${percent}%`}</span>
    </div>
  )
}

// The time, as the "Time" setting says; null for none.
function clock(now, format) {
  if (format === 'off') return null
  if (format === '12') return `${now.getHours() % 12 || 12}:${pad(now.getMinutes())}${now.getHours() < 12 ? 'am' : 'pm'}`
  return `${pad(now.getHours())}:${pad(now.getMinutes())}`
}

// What a press of the Go key does, in its own words: go, go back, go home.
function goSaid(rule, set) {
  if (rule.emit === 'back') return 'go back'
  if (rule.emit === 'forward') return 'go forward'
  if (rule.emit === 'sceneSwitcher') return set.home ? 'go home' : 'scenes'
  return said(rule).toLowerCase()
}

// How to get around, read off the frame's event map, a line each: the Go key,
// the arrows, the swipes. The home screen is where this is told: nothing on a
// scene says it (a rail of tabs beside the keys did, and was never used).
function helpLines(map, set) {
  const lines = []
  // The Go key: a press is the scene's (what is picked opens, and the layout
  // draws the picture again), unless the map binds it; twice (this list, or
  // the map's), three times and held (the map's).
  const go = []
  const goPress = keyRule(map, LIST_KEY, 'press')
  go.push(`press: ${goPress ? goSaid(goPress, set) : 'go'}`)
  const goTwice = keyRule(map, LIST_KEY, 'doublePress')
  if (goTwice) go.push(`twice: ${goSaid(goTwice, set)}`)
  else if (listKeyFree(map, set)) go.push(`twice: ${set.home ? 'go home' : 'scenes'}`)
  const goThrice = keyRule(map, LIST_KEY, 'triplePress')
  if (goThrice) go.push(`3 times: ${goSaid(goThrice, set)}`)
  const goHeld = keyRule(map, LIST_KEY, 'longPress')
  if (goHeld) go.push(`hold: ${goSaid(goHeld, set)}`)
  lines.push({ key: 'Go', text: go.join(' · ') })
  // The arrows: here they move through the list; held, the map's (a scene
  // back or on, from anywhere).
  const arrows = ['here: move']
  const upHeld = keyRule(map, 'UP', 'longPress')
  const downHeld = keyRule(map, 'DOWN', 'longPress')
  if (upHeld && downHeld && upHeld.emit === 'setCurrentScene' && downHeld.emit === 'setCurrentScene') {
    arrows.push('hold: previous / next scene')
  } else {
    if (upHeld) arrows.push(`hold up: ${said(upHeld).toLowerCase()}`)
    if (downHeld) arrows.push(`hold down: ${said(downHeld).toLowerCase()}`)
  }
  lines.push({ key: 'Up/Down', text: arrows.join(' · ') })
  const swipes = []
  if (swipeRule(map, 'bottom')) swipes.push('up: this list')
  if (swipeRule(map, 'top')) swipes.push('down: settings')
  if (swipeRule(map, 'left') || swipeRule(map, 'right')) swipes.push('sideways: back / forward')
  if (swipes.length) lines.push({ key: 'Swipe', text: swipes.join(' · ') })
  return lines
}

// The scene list, as a home screen: the time and the date over it, the
// battery and the signal, and under it how to get around.
function Home({ app, u, set }) {
  const now = new Date()
  const map = eventMap(app.frame)
  const time = clock(now, set.clock)
  // How to get around, unless the owner turned that help off.
  const help = set.swipes ? helpLines(map, set) : []

  const main = (
    <div className={`flex flex-col w-full h-full min-w-0 min-h-0 bg-[${PAPER}] text-[${INK}]`}>
      <div className={`flex items-end px-[${Math.round(u * 4)}px] pt-[${Math.round(u * 3)}px] pb-[${Math.round(u * 1.5)}px] gap-[${Math.round(u * 2)}px]`}>
        <div className="flex flex-col flex-1 min-w-0">
          {time ? <span className={`text-[${Math.round(u * 13)}px] font-bold leading-none`}>{time}</span> : null}
          {set.date ? (
            <span className={`text-[${Math.round(u * (time ? 3.6 : 6))}px] ${time ? `text-[${GREY}]` : ''} font-semibold truncate pt-[${Math.round(u)}px]`}>
              {`${DAYS[now.getDay()]}, ${now.getDate()} ${MONTHS[now.getMonth()]}`}
            </span>
          ) : null}
          {!time && !set.date ? <span className={`text-[${Math.round(u * 6)}px] font-bold leading-none`}>Scenes</span> : null}
        </div>
        <div className={`flex flex-col items-end gap-[${Math.round(u * 1.5)}px] pb-[${Math.round(u * 0.5)}px]`}>
          {set.battery ? <Battery percent={app.frame.batteryPercent} u={u} color={INK} /> : null}
          {set.signal ? <Signal rssi={app.frame.wifiRssi} u={u} color={INK} /> : null}
        </div>
      </div>
      <div className={`flex flex-col flex-1 min-h-0 border-t-2 border-[${INK}]`}>
        <yield />
      </div>
      {help.length ? (
        <div className={`flex flex-col gap-[${Math.round(u * 0.8)}px] px-[${Math.round(u * 4)}px] py-[${Math.round(u * 2)}px] border-t-2 border-[${INK}] text-[${Math.round(u * 2.9)}px]`}>
          {help.map((line) => (
            <div className={`flex items-baseline gap-[${Math.round(u * 1.5)}px] min-w-0`}>
              <span className={`shrink-0 w-[${Math.round(u * 16)}px] font-bold whitespace-nowrap`}>{line.key}</span>
              <span className={`flex-1 min-w-0 text-[${GREY}] font-semibold`}>{line.text}</span>
            </div>
          ))}
        </div>
      ) : null}
    </div>
  )
  return main
}

// The status bar: the time, the scene's name (a tap: the scene list) and the
// signal and the battery (a tap: the frame's page), over the scene.
function Bar({ app, u, set }) {
  const now = new Date()
  const time = clock(now, set.clock)
  return (
    <div className={`flex flex-col w-full h-full bg-[${PAPER}] text-[${INK}]`}>
      <div className={`flex items-center h-[${Math.round(u * 7)}px] px-[${Math.round(u * 3)}px] gap-[${Math.round(u * 2)}px] border-b-2 border-[${INK}] text-[${Math.round(u * 3.4)}px] font-bold`}>
        {time ? <span>{time}</span> : null}
        <div className="flex flex-1 items-center justify-center min-w-0 h-full gap-[4px]" onClick={() => frameos.dispatch('sceneSwitcher')}>
          <Icon d={ICON.apps} size={Math.round(u * 3.4)} />
          <span className="truncate">{app.frame.sceneName || 'Scenes'}</span>
        </div>
        <div className={`flex items-center h-full gap-[${Math.round(u * 2)}px]`} onClick={() => frameos.dispatch('sceneSettings', { page: 'frame' })}>
          {set.signal ? <Signal rssi={app.frame.wifiRssi} u={u} color={INK} /> : null}
          {set.battery ? <Battery percent={app.frame.batteryPercent} u={u} color={INK} /> : null}
        </div>
      </div>
      <div className="flex flex-col flex-1 min-h-0">
        <yield />
      </div>
    </div>
  )
}

export function get(app) {
  const frame = app.frame
  const W = frame.width
  const H = frame.height
  const set = settingsOf(app.state)
  INK = set.dark ? '#ffffff' : '#000000'
  PAPER = set.dark ? '#000000' : '#ffffff'
  GREY = set.dark ? '#aaaaaa' : '#555555'
  PALE = set.dark ? '#555555' : '#aaaaaa'
  // One unit, a hundredth of the shorter edge (the same look either way
  // round), times the "Text size".
  const u = Math.min(W, H) / 100 * set.scale
  if (listShows(frame) && set.home) {
    return <Home app={app} u={u} set={set} />
  }
  // The settings get the whole glass, and so does a scene while its keyboard is
  // up. A look this layout no longer has (the rail beside the keys, before
  // 2026.11.15) is the whole glass too.
  if (frame.systemScene || frame.typing) return <yield />
  if (app.state.look === 'bar') return <Bar app={app} u={u} set={set} />
  return <yield />
}
